-- A declared `SEQUENCE NAME` is the *user's* name and is taken verbatim — the other
-- half of the rule the auto-name implements. Reading the counter through the declared
-- name is what discriminates: a build that discards it mints `idsn_id_seq` instead,
-- and the setval below then names a sequence the catalog does not have.
-- @setup
CREATE TABLE idsn (id INT GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME idsn_custom));
SELECT setval('idsn_custom', 5, true);
INSERT INTO idsn (id) VALUES (DEFAULT);
-- @test
SELECT id FROM idsn;
